const IDS = ["b1","b2","b3","b4","b5","b6","b7","b8"]

const VERDICT = {
  type: 'object',
  properties: {
    cell: { type: 'string' },
    items: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          block: { type: 'string' },
          verdict: { type: 'string', enum: ['obeyed', 'violated', 'not_applicable'] },
          evidence: { type: 'string' },
        },
        required: ['id', 'block', 'verdict', 'evidence'],
      },
    },
    obeyed: { type: 'integer' },
    violated: { type: 'integer' },
    notApplicable: { type: 'integer' },
    notes: { type: 'string' },
  },
  required: ['cell', 'items', 'obeyed', 'violated', 'notApplicable', 'notes'],
}

log('C-0b: 8 scoping passes against the REVISED block, blind-scored on a rubric frozen before launch.')

const results = await pipeline(
  IDS,
  (id) => agent(RUNNERS[id], { label: 'run:' + id, phase: 'Run' }),
  (_report, id) => agent(SCORERS[id], { label: 'score:' + id, phase: 'Score', schema: VERDICT }),
)

return { verdicts: results.filter(Boolean) }
